SELECT event_type, CASE WHEN duration_sec >= 468 THEN 'high' WHEN duration_sec >= 193 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, COUNT(duration_sec) AS duration_sec_count, COUNT(DISTINCT duration_sec) AS unique_sessions, COUNT(*) AS row_count FROM web_events WHERE event_time >= '2025-01-01' GROUP BY event_type, CASE WHEN duration_sec >= 468 THEN 'high' WHEN duration_sec >= 193 THEN 'mid' ELSE 'low' END ORDER BY row_count, event_type
